import hashlib, json, runpy
from axiom.core import Matcher
from axiom.witness import Witness
namespace = runpy.run_path("benchmarks/performance.py")
shape = namespace["Shape"](128, "sparse", 4)
trace = namespace["Churn"]().prepare(shape, 7, 256)
results = {}
for mode in ("basic", "multilevel"):
    matcher = Matcher(128, graph=trace.graph(128), mode=mode)
    witness = Witness()
    hashes = [hashlib.sha256(witness.capture(matcher)).hexdigest()]
    for operation, left, right in trace.operations:
        getattr(matcher, operation)(left, right)
        if not matcher.maximal():
            raise RuntimeError("nonmaximal prefix")
        if matcher.multi is not None and not matcher.multi.check():
            raise RuntimeError("invalid hierarchy prefix")
        hashes.append(hashlib.sha256(witness.capture(matcher)).hexdigest())
    results[mode] = {"prefixes": hashes, "counters": vars(matcher.accountant)}
print(json.dumps({"vertices":128, "degree":4, "seed":7, "updates":256, "digest":trace.digest, "results":results}))
